sys_ws_schema.schema:
{
  "type": "object",
  "properties": {
    "table_name": {
      "type": "string",
      "description": "Target table name. Currently supported values are rm_story and pm_project."
    },
    "table_sys_id": {
      "type": "string",
      "description": "Sys ID of the Story or Project record that will receive the attachment."
    },
    "file_name": {
      "type": "string",
      "description": "Name of the attachment, including the file extension."
    },
    "content_base64": {
      "type": "string",
      "description": "Base64-encoded contents of the attachment."
    }
  },
  "required": [
    "table_name",
    "table_sys_id",
    "file_name",
    "content_base64"
  ]
}
